from pathlib import Path
import re,collections
p=Path('candidate/statement-ledger.md'); lines=p.read_text().splitlines()
heads={}; cells=[]; cur=None
for n,l in enumerate(lines,1):
 if l.startswith('## '):
  cur=l[3:].split(' (')[0]
  if ' (' in l:
   phrase=l.split(' (',1)[1][:-1]; heads[cur]=phrase.split(':',1)[0].split(' of ',1)[0]
 if n>701 and l.startswith('|'):
  fields=re.split(r'(?<"'!'"\\\\)\\|',l)[1:-1]
  if len(fields)==4 and fields[0].strip() not in ('Paper label','---'):
   cells.append((n,cur,fields[0].strip()))
tex=collections.defaultdict(list)
for f in sorted(Path('manuscript').rglob('*.tex')):
 for n,l in enumerate(f.read_text().splitlines(),1):
  for lab in re.findall(r'\\\\label\\s*\\{(["'^}]+)'"\\}',l):tex[lab].append((str(f),n,l.strip()))
problems=[]; hitsbyfile=collections.defaultdict(set)
for n in range(512,698):
 l=lines[n-1]; label=l.split('|')[1].strip().strip('"'`'"')
 hits=[(k,s) for k,s,c in cells if ('"'`'"'+label+'"'`'"' in c if label"'!='"'no direct label' else c.startswith('no direct label'))]
 actual={s for k,s in hits}; listed=re.findall(r'"'`([''^`]+)` '"\\((["'^)]+)'"\\)',l.split('|')[2])
 expect={s for s,c in listed}
 bad=[(s,c,heads.get(s)) for s,c in listed if heads.get(s)"'!=c]
 if actual!=expect or bad or (label!='"'no direct label' and label not in tex):problems.append((n,label,actual-expect,expect-actual,bad))
 if label"'!='"'no direct label':
  for f,k,t in tex[label]:hitsbyfile[f].add(k)
 if n<=604:
  grouped=collections.defaultdict(list)
  for k,s in hits:grouped[s].append(k)
  print(str(n)+' '+label+' '+ '; '.join(s+':'+','.join(map(str,ks)) for s,ks in grouped.items())+' TEX '+','.join(f+':'+str(k) for f,k,t in tex[label])+' CHECK '+('BAD' if actual"'!=expect or bad else '"'OK'))
print('ALL-ROWS PROBLEMS:',problems)
print('TABLE ROWS:',len(cells),'HEADINGS:',len(heads))
print('NO-DIRECT-WITH-LABEL:',[(n,c) for n,s,c in cells if c.startswith('no direct label') and re.search(r'"'`[''^`]*:[''^`]*`'"',c)])
