from pathlib import Path
import re,collections
lines=Path('candidate/statement-ledger.md').read_text().splitlines(); cells=[];cur=None
for n,l in enumerate(lines,1):
 if l.startswith('## '):cur=l[3:].split(' (')[0]
 if n>701 and l.startswith('|'):
  fs=re.split(r'(?<"'!'"\\\\)\\|',l)[1:-1]
  if len(fs)==4 and fs[0].strip() not in ('Paper label','---'):cells.append((n,cur,fs[0].strip()))
tex=collections.defaultdict(list);used=collections.defaultdict(set)
for f in sorted(Path('manuscript').rglob('*.tex')):
 for n,l in enumerate(f.read_text().splitlines(),1):
  for lab in re.findall(r'\\\\label\\s*\\{(["'^}]+)'"\\}',l):tex[lab].append((str(f),n))
for n in range(512,698):
 label=lines[n-1].split('|')[1].strip().strip('"'`'"')
 for f,k in tex[label]:used[f].add(k)
