 hits=[(k,s) for k,s,c in cells if ('"'`'"'+label+'"'`'"' in c if label"'!='"'no direct label' else c.startswith('no direct label'))];grouped=collections.defaultdict(list)
 for k,s in hits:grouped[s].append(k)
 def ranges(ks):
  out=[]
  for k in ks:
   if out and k==out[-1][-1]+1:out[-1].append(k)
   else:out.append([k])
  return ','.join(str(a[0])+('-'+str(a[-1]) if len(a)>1 else '') for a in out)
 print(str(n)+' '+label+' '+ '; '.join(s+':'+ranges(ks) for s,ks in grouped.items())+' TEX '+','.join(f+':'+str(k) for f,k in tex[label]))
